def normalize_identity(value):
    return " ".join(value.strip().casefold().split())

roommate_emails = {normalize_identity(contact["email"]) for contact in roommate_contacts if normalize_identity(contact["email"])}
roommate_names = {normalize_identity(" ".join([contact["first_name"], contact["last_name"]])) for contact in roommate_contacts if normalize_identity(" ".join([contact["first_name"], contact["last_name"]]))}
today_key = current_date_time["date"].strip()[:10]

def participant_is_roommate(participant):
    participant_email = normalize_identity(participant["email"])
    participant_name = normalize_identity(participant["name"])
    return (bool(participant_email) and participant_email in roommate_emails) or (bool(participant_name) and participant_name in roommate_names)

def transaction_is_target(transaction):
    transaction_date = transaction["created_at"].strip().split("T", 1)[0].split(" ", 1)[0]
    return transaction_date == today_key and (participant_is_roommate(transaction["sender"]) or participant_is_roommate(transaction["receiver"]))

target_transactions = [transaction for transaction in social_feed if transaction_is_target(transaction)]
target_transaction_ids = list(dict.fromkeys(transaction["transaction_id"] for transaction in target_transactions))
